import React from 'react';
import { HorizontalBarChartProps } from './types';
/**

  A Horizontal bar chart or bar graph is a chart or graph that presents categorical data with rectangular
  bars with width and length using the [AMCharts 5 library](https://www.amcharts.com/docs/v5/)
  
  ### Example Usage:
 
  ```tsx
  import * as React from "react";
  import HorizontalBarChart from '@walmart-dataventures/chart-components';
 
  export default () => {
    const data = [{ name: 'John', value: 35654 }, { name: 'Damon', value: 65456 }];

    const xAxisSettings = {
       categoryAxisSettings: {
    maxDeviation: 0,
  },
  rendererGridTemplateSettings: {
    strokeDasharray: [2, 2],
  },
    };

    const yAxisSettings = {
      categoryAxisSettings: {
        maxDeviation: 0,
        min: 0,
        extraMax: 0.1,
        categoryField: 'name',
      },
    };

    const seriesSettings = {
      columnSettings: {
        name: 'Series 1',
        valueXField: 'value',
        sequencedInterpolation: true,
        categoryYField: 'name',
      }
      tooltipSettings: { dy: -25, labelText: '{valueX}' },
    };

    return <HorizontalBarChart data={data} xAxisSettings={xAxisSettings} yAxisSettings={yAxisSettings} seriesSettings={seriesSettings}/>;
  };
  ```
  
  ### References

  https://www.amcharts.com/docs/v5/charts/xy-chart/
  
  https://www.amcharts.com/docs/v4/concepts/axes/axis-ranges/#Range_labels

 */
export declare const HorizontalBarChart: React.FC<HorizontalBarChartProps>;
